<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, Edit3, Check, Users, FileText, WandSparkles } from '@lucide/vue'
import { api } from '../api'
const route=useRoute();const router=useRouter();const id=Number(route.params.id)
const meeting=ref<any>(null);const segments=ref<any[]>([]);const suggestions=ref<any[]>([]);const editing=ref<number|null>(null);const draft=ref('');const error=ref('');const suggesting=ref(false)
const fmt=(ms:number)=>`${String(Math.floor(ms/60000)).padStart(2,'0')}:${String(Math.floor(ms%60000/1000)).padStart(2,'0')}`
async function load(){try{const [m,t,s]=await Promise.all([api(`/meetings/${id}`),api(`/meetings/${id}/transcript`),api(`/meetings/${id}/speaker-suggestions`,{method:'POST'})]);meeting.value=m;segments.value=t.items;suggestions.value=s.items}catch(e:any){error.value=e.message}}
async function suggestWithAi(){suggesting.value=true;error.value='';try{suggestions.value=(await api(`/meetings/${id}/speaker-suggestions?use_ai=true`,{method:'POST'})).items}catch(e:any){error.value=e.message}finally{suggesting.value=false}}
function edit(item:any){editing.value=item.id;draft.value=item.text}
async function save(item:any){try{const updated=await api(`/transcript-segments/${item.id}`,{method:'PATCH',body:JSON.stringify({text:draft.value})});Object.assign(item,updated);editing.value=null}catch(e:any){error.value=e.message}}
async function rename(label:string,name:string){try{const targets=segments.value.filter(v=>v.speaker_label===label);await Promise.all(targets.map(v=>api(`/transcript-segments/${v.id}`,{method:'PATCH',body:JSON.stringify({speaker_name:name})})));targets.forEach(v=>v.speaker_name=name)}catch(e:any){error.value=e.message}}
onMounted(load)
</script>
<template><div v-if="!meeting&&!error" class="loading">LOADING TRANSCRIPT…</div><div v-else-if="error&&!meeting" class="notice error">{{error}}</div><div v-else><section class="page-heading"><div><button class="button compact" @click="router.push(`/meetings/${id}`)"><ArrowLeft :size="16"/>会议详情</button><div class="eyebrow" style="margin-top:24px">Transcript / {{segments.length}} segments</div><h1>{{meeting.title}}<br>逐字转写</h1><p>修正说话人和文本后，证据引用仍保留片段身份。</p></div><div class="detail-actions"><button class="button" @click="suggestWithAi" :disabled="suggesting||!segments.length"><WandSparkles :size="16"/>{{suggesting?'正在分析…':'AI 建议说话人'}}</button><button class="button primary" @click="router.push(`/meetings/${id}/minutes`)"><FileText :size="17"/>查看纪要</button></div></section><div v-if="error" class="notice error" style="margin-bottom:16px">{{error}}</div><div class="transcript-layout"><section class="card paper"><div v-if="!segments.length" class="empty">还没有转写片段。请先上传资料并提交转写任务。</div><div v-else class="transcript-list"><article v-for="item in segments" :id="`segment-${item.id}`" :key="item.id" class="segment"><span class="time">{{fmt(item.start_ms)}}</span><span class="speaker">{{item.speaker_name||item.speaker_label}}</span><textarea v-if="editing===item.id" v-model="draft" style="width:100%;min-height:90px;border:1px solid var(--teal);border-radius:9px;padding:10px;background:white"/><p v-else>{{item.text}}</p><button v-if="editing===item.id" class="icon-btn" @click="save(item)"><Check :size="16"/></button><button v-else class="icon-btn" @click="edit(item)"><Edit3 :size="15"/></button></article></div></section><aside class="side-sticky"><div class="card"><header class="card-header"><div><div class="kicker">Speaker map</div><h2>说话人</h2></div><Users :size="22"/></header><p>先用规则建议，再按需调用模型分析；确认后才会批量更新。</p><div class="speaker-map"><label v-for="item in suggestions" :key="item.speaker_label"><span><span class="mono" style="font-size:10px">{{item.speaker_label}}</span><strong style="display:block;margin-top:4px">{{item.suggested_name}}</strong><small>{{item.source==='ai'?'AI 建议':'初始建议'}} · {{Math.round(item.confidence*100)}}%</small></span><button class="button compact" @click="rename(item.speaker_label,item.suggested_name)">采用</button></label></div></div></aside></div></div></template>
